// Retrieves the content of the message referenced by the provided message
// URI. If the message content does not already exist in the offline store, it
// is downloaded, stored, and then served.
//
// If `displayDocShell` is not null, then it is used to render the message.
// Otherwise, if `streamListener` is not null, the message content is streamed
// to it.
nsresult GetMessageContent(const nsACString& messageURI,
                           nsIDocShell* displayDocShell,
                           nsIStreamListener* streamListener);

// Downloads the content of the message referenced by the given message URI.
// Once the message content has been downloaded, it is stored to the relevant
// offline store, and passed onto the provided docshell or stream listener
// similarly to `GetMessageContent`.
nsresult DownloadMessage(nsIURI* messageURI, nsIMsgDBHdr* hdr,
                         nsIDocShell* displayDocShell,
                         nsIStreamListener* streamListener);

// Other cases (with `convert=true` in the query) likely originate from using
// `ExchangeService::StreamMessage`. In theory we could run the stream
// converter there directly, but we want to centralise calls to the stream
// converter service as much as possible for maintainability.
bool convert = false;
if (spec.Find("part=") != kNotFound ||
    spec.Find("convert=true") != kNotFound) {
  convert = true;
}

RefPtr<ExchangeMessageChannel> channel =
    new ExchangeMessageChannel(aURI, convert);

nsresult ExchangeService::FetchMessage(nsIURI* aURI,
                                       nsIStreamListener* aStreamListener) {
  nsCOMPtr<nsIIOService> netService = mozilla::components::IO::Service();
  NS_ENSURE_TRUE(netService, NS_ERROR_UNEXPECTED);

  nsCOMPtr<nsIChannel> messageChannel;
  MOZ_TRY(netService->NewChannelFromURI(
      aURI, nullptr, nsContentUtils::GetSystemPrincipal(), nullptr,
      nsILoadInfo::SEC_ALLOW_CROSS_ORIGIN_SEC_CONTEXT_IS_NULL,
      nsIContentPolicy::TYPE_OTHER, getter_AddRefs(messageChannel)));

  return messageChannel->AsyncOpen(aStreamListener);
